{"operation":"run_python","code":"def simulate(r, b, offset_R=0, offset_B=0):
    # Generate events in (0, r*b]
    events = []
    for i in range(1, r+1):
        t = i*r + offset_R
        if 0 < t <= r*b:
            events.append((t, 'R'))
    for i in range(1, b+1):
        t = i*b + offset_B
        if 0 < t <= r*b:
            events.append((t, 'B'))
    events.sort(key=lambda x: x[0])

    stack = []
    for _, color in events:
        stack.append(color)
        while len(stack) >= 2 and stack[-1] == stack[-2]:
            stack.pop()
            stack.pop()
    return len(stack), ''.join(c for _, c in events)

# Test part (a): r, b odd
results = {}
for r in [1, 3, 5]:
    for b in [1, 3, 5]:
        if r == b: continue
        # Try a few offsets to see if it's constant
        vals = set()
        for oR in range(r):
            for oB in range(b):
                # Check no collision
                collide = False
                for i in range(1, r+1):
                    tR = i*r + oR
                    for j in range(1, b+1):
                        tB = j*b + oB
                        if 0 < tR <= r*b and 0 < tB <= r*b and tR == tB:
                            collide = True
                            break
                    if collide: break
                if not collide:
                    L, seq = simulate(r, b, oR, oB)
                    vals.add(L)
        results[(r,b)] = vals

print("Part (a) results:", results)
"}

{"operation":"run_python","code":"def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

divs = [2, 3, 6, 7, 14, 21, 42, 49, 98, 147, 294]
n = len(divs)
adj = {d: [] for d in divs}
for i in range(n):
    for j in range(i+1, n):
        if gcd(divs[i], divs[j]) > 1:
            adj[divs[i]].append(divs[j])
            adj[divs[j]].append(divs[i])

# Find all Hamiltonian cycles
cycles = []
def find_cycles(path, visited):
    if len(path) == n:
        if divs[-1] in adj[path[0]] and path[0] in adj[path[-1]]: # actually just check last to first
            pass # we need to check adjacency of last and first
        # Check if last connects to first
        if adj[path[-1]][-1] == path[0] or path[0] in adj[path[-1]]:
            cycles.append(path[:])
        return

    curr = path[-1]
    for neighbor in adj[curr]:
        if neighbor not in visited:
            visited.add(neighbor)
            path.append(neighbor)
            find_cycles(path, visited)
            path.pop()
            visited.remove(neighbor)

start = divs[0] # start with 2 to fix rotation
find_cycles([start], {start})

print(f"Found {len(cycles)} cycles.")
for c in cycles:
    idx = c.index(21)
    left = c[idx-1]
    right = c[(idx+1)%n]
