def count_digits_primorial(p):
    is_prime = bytearray([1]) * (p + 1)
    is_prime[0] = 0
    is_prime[1] = 0
    for i in range(2, int(math.isqrt(p)) + 1):
        if is_prime[i]:
            is_prime[i*i:p+1:i] = bytearray([0]) * len(range(i*i, p+1, i))

    sum_ln_p = 0.0
    for i in range(2, p + 1):
        if is_prime[i]:
            sum_ln_p += math.log(i)

    digits = math.floor(sum_ln_p / math.log(10)) + 1
    return digits, sum_ln_p

