{"operation":"run_python","code":"def max_cut(n):
    import itertools
    best = -1
    best_config = None
    # Build adjacency list for king's graph
    adj = {}
    for i in range(n):
        for j in range(n):
            u = i * n + j
            neighbors = []
            for di in [-1, 0, 1]:
                for dj in [-1, 0, 1]:
                    if di == 0 and dj == 0: continue
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < n:
                        neighbors.append(ni * n + nj)
            adj[u] = neighbors

    total_edges = sum(len(adj[u]) for u in range(n*n)) // 2

    # Try all $2^{n^2}$ colorings
    for mask in range(1 << (n*n)):
        cut = 0
        for u in range(n*n):
            if (mask >> u) & 1: # black
                for v in adj[u]:
                    if not ((mask >> v) & 1): # white
                        cut += 1
        if cut > best:
            best = cut
            best_config = mask

    return best, total_edges

print("n=3:", max_cut(3))
print("n=4:", max_cut(4))"}

