{"operation":"run_python","code":"def solve():
    # Grid representation: 0 for empty, else the number
    grid = [
        [0, 0, 1, 0],
        [0, 3, 0, 0],
        [0, 0, 0, 0],
        [0, 0, 2, 1]
    ]

    def is_valid(g, r, c, num):
        # Check row
        if num in g[r]: return False
        # Check col
        for i in range(4):
            if g[i][c] == num: return False
        # Check 2x2 square
        start_r, start_c = (r // 2) * 2, (c // 2) * 2
        for i in range(start_r, start_r + 2):
            for j in range(start_c, start_c + 2):
                if g[i][j] == num: return False
        return True

    def solve_grid(g):
        for r in range(4):
            for c in range(4):
                if g[r][c] == 0:
                    for num in range(1, 5):
                        if is_valid(g, r, c, num):
                            g[r][c] = num
                            if solve_grid(g): return True
                            g[r][c] = 0
                    return False
        return True

    if solve_grid(grid):
        for row in grid:
            print(row)
        # Find positions of 4
        for r in range(4):
            for c in range(4):
                if grid[r][c] == 4:
                    print(f"Row {chr(65+r)} has 4 at column {c+1}")
    else:
        print("No solution")

solve()"}

