{"operation":"run_python","code":"import itertools

def max_clique_size(m):
    subsets = list(itertools.combinations(range(m), 4))
    n_subsets = len(subsets)

    # Build adjacency matrix: 1 if intersection is even (0 or 2), 0 otherwise
    adj = [[0]*n_subsets for _ in range(n_subsets)]
    for i in range(n_subsets):
        for j in range(i+1, n_subsets):
            inter = len(set(subsets[i]) & set(subsets[j]))
            if inter % 2 == 0:
                adj[i][j] = 1
                adj[j][i] = 1

    # Find max clique using Bron-Kerbosch or simple backtracking since n is small for m<=10
    best_clique = []

    def backtrack(current_clique, candidates):
        nonlocal best_clique
        if not candidates:
            if len(current_clique) > len(best_clique):
                best_clique = list(current_clique)
            return

        # Optimization: if remaining + current <= best, prune
        if len(current_clique) + len(candidates) <= len(best_clique):
            return

        for i in range(len(candidates)):
            node = candidates[i]
            # Check if node is connected to all in current_clique
            if all(adj[node][c] for c in current_clique):
                # New candidates are those after i that are also connected to node
                new_candidates = [c for c in candidates[i+1:] if adj[node][c]]
                backtrack(current_clique + [node], new_candidates)

    backtrack([], list(range(n_subsets)))
    return len(best_clique), best_clique

for m in range(4, 12, 2):
    size, clique = max_clique_size(m)
    print(f"m={m}, max n={size}")
    if m <= 8:
        print([subsets[i] for i in clique])"}

