{"operation":"run_python","code":"def max_nested_diff(n):
    from itertools import permutations
    max_val = 0
    best_perm = None
    for p in permutations(range(1, n+1)):
        val = abs(p[0] - p[1])
        for i in range(2, n):
            val = abs(val - p[i])
        if val > max_val:
            max_val = val
            best_perm = p
    return max_val, best_perm

