{"operation":"run_python","code":"def max_cycle_weight(n):
    from itertools import permutations
    def dist(i, j):
        return min(abs(i-j), n-abs(i-j))

    max_w = 0
    # To reduce symmetry, fix p[0] = 0
    for perm in permutations(range(1, n)):
        p = [0] + list(perm)
        w = sum(dist(p[i], p[(i+1)%n]) for i in range(n))
        if w > max_w:
            max_w = w
    return max_w

for n in [2, 4, 6, 8]:
    print(f"n={n}: {max_cycle_weight(n)}")"}

